/* ============================================================================
   INTENSITY TAILS AND THE THIN POOLS — v5
   ----------------------------------------------------------------------------
   §5's structural finding, restated: effective variety at any slider position is
   roughly "how many traits this category holds within about 0.73 position units
   of the target". So adding mid-range content does not increase variety at a
   given slider setting — it spreads the same window thinner across the whole
   slider. Only TAIL content moves the ends, and the ends are where users push
   when they want a strong character.

   Measured across the bank: i1 is 10.1% and i5 is 6.3%, so 16.4% of the content
   is serving the outer half of every slider's travel.

   Closing that everywhere means about fifteen traits per category per intensity
   across 120 categories, which is a multi-thousand-entry project and not this
   one. This file does the pools the audit names specifically, which are the ones
   where the gap is actually reachable by a user:

   1. THE SITUATIONAL POOLS. 40-41 traits each, nine of thirteen thin at i1 or
      i4/i5 — and they serve the entire neutral band, which is the default state
      of every untouched slider and therefore the highest-traffic content in the
      app. (The neutral personality draw now also reaches the quiet end of both
      poles, which widened these considerably; this fills their own tails so the
      pronounced end of "situational" is reachable at all.)

   2. THE NEED / THE GHOST / THE DEFENCE. 40 each against Core Want's 77. These
      three are the most writerly categories in the tool — they are what turns a
      wound into a story — and they were the thinnest in their own section.

   3. APPEARANCE. 31-41 per category across eight categories, six of them thin at
      both i1 and i5, and the least causally connected section in the bank.

   4. MICRO-PHYSICAL TICS (3 at i4, 2 at i5) and CONCEPTUAL FRAMEWORK & LOANWORDS
      (4 at i4, 3 at i5) — the audit's example of a setting that is simply not
      reachable: "aggressively jargon-heavy" had almost nothing to draw.

   ids start at 150000.
   ========================================================================== */
const TRAITS_TAILS2 = [

/* ================================================================
   1. SITUATIONAL POOLS — the i1 and i4/i5 tails
   ----------------------------------------------------------------
   At i1: conditionality so slight it is barely worth the word.
   At i4/i5: conditionality so pronounced that it IS the fact about them.
   ================================================================ */

/* ---- Friendliness — Situational ---- */
{id:150001,section:"Personality Traits",category:"Friendliness — Situational",trait:"A shade warmer after lunch",desc:"The variation is real, tiny, and entirely predictable.",example:"<i>(marginally more forthcoming from about two o'clock)</i>",intensity:1,rarity:"common",pol:{warm:0}},
{id:150002,section:"Personality Traits",category:"Friendliness — Situational",trait:"Warmth on a strict rota",desc:"Different people get measurably different versions, and the allocation never varies.",example:"He's lovely with the customers. Ask anyone who works for him.",intensity:4,rarity:"distinctive",pol:{warm:0,hon:-1}},
{id:150003,section:"Personality Traits",category:"Friendliness — Situational",trait:"Two entirely separate people",desc:"The public and private versions are so far apart that meeting both is disorienting.",example:"<i>(the door closes, and someone else is standing there)</i>",intensity:5,rarity:"signature",pol:{warm:0,hon:-1}},
{id:150004,section:"Personality Traits",category:"Friendliness — Situational",trait:"Warmer to whoever arrived last",desc:"A small, consistent bias toward the newest person in the room.",example:"<i>(turns fully toward the door each time it opens)</i>",intensity:1,rarity:"uncommon",pol:{}},

/* ---- Honesty — Situational ---- */
{id:150005,section:"Personality Traits",category:"Honesty — Situational",trait:"Rounds down by a little",desc:"A habit of slight understatement so small nobody would call it lying.",example:"Cost about forty. <i>(It was forty-six.)</i>",intensity:1,rarity:"common",pol:{hon:0}},
{id:150006,section:"Personality Traits",category:"Honesty — Situational",trait:"Honest with exactly one person",desc:"Everyone else gets a managed version, and the exception is absolute.",example:"You're the only one who gets this. That's not a compliment, it's a warning.",intensity:4,rarity:"distinctive",pol:{hon:0,emo:1}},
{id:150007,section:"Personality Traits",category:"Honesty — Situational",trait:"Truth calibrated to the room",desc:"Reads what the room can take and supplies exactly that much, every time, without effort.",example:"<i>(three people, three different accounts, none of them false)</i>",intensity:5,rarity:"signature",pol:{hon:0,intel:1}},
{id:150008,section:"Personality Traits",category:"Honesty — Situational",trait:"Truthful about small things by default",desc:"A default toward accuracy on trivia that says nothing about anything larger.",example:"It was Tuesday, not Wednesday. <i>(He is lying about the rest of it.)</i>",intensity:1,rarity:"uncommon",pol:{}},

/* ---- Assertiveness — Situational ---- */
{id:150009,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Firm about the small print",desc:"Yields on everything except details, and only mildly there.",example:"That's fine — it's 'by', not 'on', though.",intensity:1,rarity:"common",pol:{}},
{id:150010,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Immovable on one subject only",desc:"Entirely accommodating across their whole life apart from a single topic where they cannot be shifted at all.",example:"Anything you like. Not the house. Never the house.",intensity:4,rarity:"distinctive",pol:{asrt:0}},
{id:150011,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Assertive exactly in proportion to the stakes",desc:"Silent on small things and completely immovable on large ones, with no middle setting.",example:"<i>(said nothing for an hour, then ended the meeting in a sentence)</i>",intensity:5,rarity:"signature",pol:{asrt:0,intel:1}},
{id:150012,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Speaks up second",desc:"Never first and never last; goes once somebody else has broken the ice.",example:"<i>(waits for one person to have spoken, then adds theirs)</i>",intensity:1,rarity:"uncommon",pol:{}},

/* ---- Confidence — Situational ---- */
{id:150013,section:"Personality Traits",category:"Confidence — Situational",trait:"Steady until photographed",desc:"Entirely composed apart from one small, specific trigger.",example:"<i>(the phone comes out, and the shoulders go up an inch)</i>",intensity:1,rarity:"uncommon",pol:{}},
{id:150014,section:"Personality Traits",category:"Confidence — Situational",trait:"Unshakeable in their own field, lost outside it",desc:"The gap between the two is wide enough to look like two different people.",example:"<i>(commands the workshop; cannot order a coffee)</i>",intensity:4,rarity:"distinctive",pol:{ego:0}},
{id:150015,section:"Personality Traits",category:"Confidence — Situational",trait:"Confidence borrowed from whoever is present",desc:"Has no independent setting at all; takes the level of the room and matches it exactly.",example:"<i>(with her: certain. Alone: nothing at all.)</i>",intensity:5,rarity:"signature",pol:{ego:0,agr:1}},
{id:150016,section:"Personality Traits",category:"Confidence — Situational",trait:"Surer on the phone",desc:"A small, reliable lift when they cannot be seen.",example:"<i>(the voice does something it never does face to face)</i>",intensity:1,rarity:"common",pol:{}},

/* ---- Agreeableness — Situational ---- */
{id:150017,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Agrees faster when tired",desc:"A mild, entirely predictable drift toward whatever is easiest late in the day.",example:"<i>(it's gone six; everything is fine now)</i>",intensity:1,rarity:"common",pol:{}},
{id:150018,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Contrary to authority, agreeable to everyone else",desc:"A sharp, consistent split that depends entirely on who is asking.",example:"Course, no problem. — <i>(to the manager)</i> — Why?",intensity:4,rarity:"distinctive",pol:{agr:0,rebel:1}},
{id:150019,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Position determined entirely by the last speaker",desc:"So responsive to the room that they hold no stable view at all, and know it.",example:"I thought that too, until you said. Now I don't.",intensity:5,rarity:"signature",pol:{agr:0,ego:-1}},
{id:150020,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Goes along with the seating",desc:"Accommodating about arrangements and nothing else.",example:"Wherever. Genuinely, wherever.",intensity:1,rarity:"uncommon",pol:{}},

/* ---- Manners — Situational ---- */
{id:150021,section:"Personality Traits",category:"Manners — Situational",trait:"Remembers to say please half the time",desc:"An inconsistency too small for anyone to have mentioned.",example:"Pass the — thanks. Sorry: could you pass the salt.",intensity:1,rarity:"common",pol:{}},
{id:150022,section:"Personality Traits",category:"Manners — Situational",trait:"Immaculate manners as a weapon",desc:"Courtesy that sharpens precisely when they are furious, and everyone learns to dread it.",example:"Thank you <i>so</i> much for explaining that to me.",intensity:4,rarity:"distinctive",pol:{man:0,agr:-1}},
{id:150023,section:"Personality Traits",category:"Manners — Situational",trait:"A different rulebook per postcode",desc:"Observes an entirely separate code of conduct in each part of their life, fluently, with no bleed between them.",example:"<i>(three sets of manners, three sets of people, never once confused)</i>",intensity:5,rarity:"signature",pol:{man:0,intel:1}},
{id:150024,section:"Personality Traits",category:"Manners — Situational",trait:"Holds doors, forgets names",desc:"Half the courtesies are automatic and the other half were never learned.",example:"<i>(door held perfectly; 'mate' for the fourth time)</i>",intensity:1,rarity:"uncommon",pol:{}},

/* ---- Discipline — Situational ---- */
{id:150025,section:"Personality Traits",category:"Discipline — Situational",trait:"Organised in one drawer",desc:"A single well-kept corner in an otherwise unmanaged life.",example:"<i>(the toolbox is immaculate. Nothing else is.)</i>",intensity:1,rarity:"common",pol:{}},
{id:150026,section:"Personality Traits",category:"Discipline — Situational",trait:"Rigorous for other people, chaotic for themselves",desc:"Never once late for anyone else and never once on time for anything of their own.",example:"<i>(your deadline was met. His has been moved four times.)</i>",intensity:4,rarity:"distinctive",pol:{disc:0,agr:1}},
{id:150027,section:"Personality Traits",category:"Discipline — Situational",trait:"Total discipline in bursts, then nothing",desc:"Alternates between complete rigour and complete collapse on a cycle everyone around them has learned to read.",example:"<i>(five weeks of everything. Then three of nothing.)</i>",intensity:5,rarity:"signature",pol:{disc:0}},
{id:150028,section:"Personality Traits",category:"Discipline — Situational",trait:"Punctual only for trains",desc:"One category of appointment is sacred; everything else is approximate.",example:"<i>(forty minutes early for the 8:12. Twenty late for dinner.)</i>",intensity:1,rarity:"uncommon",pol:{}},

/* ---- Rebelliousness — Situational ---- */
{id:150029,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Bends one rule regularly",desc:"A single, small, habitual non-compliance nobody has ever challenged.",example:"<i>(parks in the same wrong space every day)</i>",intensity:1,rarity:"common",pol:{}},
{id:150030,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Compliant until it's written down",desc:"Cooperative with a request and immediately resistant to the same thing as policy.",example:"Yeah, of course. — <i>(reads the memo)</i> — Now I'm not doing it.",intensity:4,rarity:"distinctive",pol:{rebel:0}},
{id:150031,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Obedience calibrated to whether it's watched",desc:"Perfect compliance in view and none whatever out of it, with no apparent internal conflict.",example:"<i>(exemplary on the floor. Something else entirely in the yard.)</i>",intensity:5,rarity:"signature",pol:{rebel:0,hon:-1}},
{id:150032,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Defers to anyone in a uniform",desc:"A narrow, reliable exception to an otherwise ordinary independence.",example:"<i>(argues with everyone; not with the guard)</i>",intensity:1,rarity:"uncommon",pol:{}},

/* ---- Emotional Capacity — Situational ---- */
{id:150033,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Open about the past, closed about now",desc:"Will discuss anything more than five years old and nothing current.",example:"Oh, back then, God, yes. — This week? Fine.",intensity:1,rarity:"common",pol:{}},
{id:150034,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Open only in transit",desc:"Says the real things in cars, on walks and on the phone, and never sitting still facing someone.",example:"<i>(forty minutes of nothing at the table; everything on the way home)</i>",intensity:4,rarity:"distinctive",pol:{emo:0}},
{id:150035,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Openness on a strict schedule",desc:"Available emotionally in defined windows and completely unreachable outside them, and everyone knows the timetable.",example:"Not now. Sunday. We'll do it Sunday.",intensity:5,rarity:"signature",pol:{emo:0,disc:1}},
{id:150036,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Softer about other people's children",desc:"One narrow subject reliably gets past the guard.",example:"<i>(entirely different voice for about four seconds)</i>",intensity:1,rarity:"uncommon",pol:{}},

/* ---- Intelligence — Situational ---- */
{id:150037,section:"Personality Traits",category:"Intelligence — Situational",trait:"Sharper in writing",desc:"A small, consistent difference between what they say and what they send.",example:"<i>(mumbles through the meeting; the email is immaculate)</i>",intensity:1,rarity:"common",pol:{}},
{id:150038,section:"Personality Traits",category:"Intelligence — Situational",trait:"Brilliant under pressure, ordinary without it",desc:"Needs a crisis to think properly and is unremarkable in calm.",example:"<i>(nothing all week; then twenty minutes of something extraordinary)</i>",intensity:4,rarity:"distinctive",pol:{intel:0}},
{id:150039,section:"Personality Traits",category:"Intelligence — Situational",trait:"Thinks only in the presence of a problem",desc:"No abstract capacity at all and a formidable concrete one, and the switch is total.",example:"Don't ask me in general. Show me the actual broken thing.",intensity:5,rarity:"signature",pol:{intel:0}},
{id:150040,section:"Personality Traits",category:"Intelligence — Situational",trait:"Quicker about other people's problems",desc:"A mild and very common asymmetry, unremarked.",example:"<i>(solves hers in a sentence; his has been open for a year)</i>",intensity:1,rarity:"uncommon",pol:{}},

/* ---- Positivity — Situational ---- */
{id:150041,section:"Personality Traits",category:"Positivity — Situational",trait:"Cheerful before eleven",desc:"A small and entirely reliable diurnal pattern.",example:"<i>(the good mood has a shelf life and everyone knows when)</i>",intensity:1,rarity:"common",pol:{}},
{id:150042,section:"Personality Traits",category:"Positivity — Situational",trait:"Optimistic about people, bleak about institutions",desc:"A clean split that holds absolutely, in both directions.",example:"They'll be fine. The system won't help them, but they'll be fine.",intensity:4,rarity:"distinctive",pol:{pos:0}},
{id:150043,section:"Personality Traits",category:"Positivity — Situational",trait:"Hope rationed to one thing at a time",desc:"Capable of exactly one live hope, and visibly closes the others while it runs.",example:"I'm not thinking about any of the rest of it until this is settled.",intensity:5,rarity:"signature",pol:{pos:0,disc:1}},
{id:150044,section:"Personality Traits",category:"Positivity — Situational",trait:"Sunnier outdoors",desc:"A mild, physical dependence on daylight that they have never remarked on.",example:"<i>(different person on the walk back)</i>",intensity:1,rarity:"uncommon",pol:{}},

/* ---- Activeness — Situational ---- */
{id:150045,section:"Personality Traits",category:"Activeness — Situational",trait:"Hands going, body parked",desc:"Almost motionless overall, with one part of them always going.",example:"<i>(hasn't shifted in the chair; the fingers have not stopped)</i>",intensity:1,rarity:"common",pol:{}},
{id:150046,section:"Personality Traits",category:"Activeness — Situational",trait:"Tireless for other people, immobile for themselves",desc:"Will move mountains on request and cannot get up for their own errands.",example:"<i>(drove ninety miles for her. The bins have been out four days.)</i>",intensity:4,rarity:"distinctive",pol:{act:0,agr:1}},
{id:150047,section:"Personality Traits",category:"Activeness — Situational",trait:"Energy entirely dependent on company",desc:"Fast and physical with people and completely inert alone, with nothing in between.",example:"<i>(the door shuts and they sit down for four hours)</i>",intensity:5,rarity:"signature",pol:{act:0}},
{id:150048,section:"Personality Traits",category:"Activeness — Situational",trait:"Paces on the phone only",desc:"One narrow, unconscious exception to an otherwise still person.",example:"<i>(the call starts; the circuit of the kitchen begins)</i>",intensity:1,rarity:"uncommon",pol:{}},

/* ---- Curiosity — Situational ---- */
{id:150049,section:"Personality Traits",category:"Curiosity — Situational",trait:"Curious about machines only",desc:"A narrow interest, mildly held, in one class of thing.",example:"<i>(has taken the back off the radio; has never asked about her family)</i>",intensity:1,rarity:"common",pol:{}},
{id:150050,section:"Personality Traits",category:"Curiosity — Situational",trait:"Endlessly curious about strangers, incurious about friends",desc:"Interrogates new people thoroughly and has never asked the old ones anything.",example:"So what took you there? — <i>(has known Dave for eleven years)</i>",intensity:4,rarity:"distinctive",pol:{cur:0}},
{id:150051,section:"Personality Traits",category:"Curiosity — Situational",trait:"Curiosity that switches off at competence",desc:"Consumed by anything they cannot do yet and instantly finished with it once they can.",example:"<i>(a shed of abandoned mastered hobbies)</i>",intensity:5,rarity:"signature",pol:{cur:0,disc:-1}},
{id:150052,section:"Personality Traits",category:"Curiosity — Situational",trait:"Reads the back of packets",desc:"Small, idle, harmless investigation of whatever is at hand.",example:"<i>(now knows the sodium content of everything in the cupboard)</i>",intensity:1,rarity:"uncommon",pol:{}},

/* ================================================================
   2. THE NEED / THE GHOST / THE DEFENCE
   ----------------------------------------------------------------
   40 each against Core Want's 77, and these three are what turn a
   wound into a story.
   ================================================================ */

/* ---- The Need (what would actually help) ---- */
{id:150060,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"To be argued with",desc:"Wants agreement; needs one person who will not give it and stays anyway.",example:"Everyone says yes to me. I've noticed. I've started to hate it.",intensity:3,rarity:"distinctive",pol:{agr:-1,hon:1}},
{id:150061,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"To finish something badly and survive it",desc:"Wants to do it perfectly; needs one completed, flawed, public thing.",example:"I've started nine. I've finished none. They'd all have been fine.",intensity:3,rarity:"distinctive",pol:{disc:-1,ego:-1}},
{id:150062,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"To be no use to anyone for a week",desc:"Wants to be indispensable; needs to find out what is there when they are not.",example:"If I went away, who would — no. That's the question, isn't it.",intensity:4,rarity:"signature",pol:{agr:-1,disc:-1}},
{id:150063,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"To hear the whole of it, unsoftened",desc:"Wants reassurance; needs the accurate account from someone who won't manage them.",example:"Don't do the kind version. I can tell when you're doing the kind version.",intensity:3,rarity:"distinctive",pol:{hon:1,emo:1}},
{id:150064,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"A room nobody else has a key to",desc:"Wants to be included; needs one place that is theirs and only theirs.",example:"Everything I own is in a room somebody else also uses.",intensity:2,rarity:"distinctive",pol:{emo:-1}},
{id:150065,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"To be the one who is looked after, once",desc:"Wants to be capable; needs to be on the receiving end of it a single time.",example:"I don't actually know what that would feel like.",intensity:4,rarity:"signature",pol:{warm:1,ego:-1}},
{id:150066,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"An ordinary week",desc:"Wants the crisis resolved; needs to find out they can tolerate nothing happening.",example:"I'm fine when it's on fire. It's the Tuesdays I can't do.",intensity:2,rarity:"distinctive",pol:{act:-1,mood:1}},
{id:150067,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"To stop being the interesting one",desc:"Wants attention; needs one relationship where they are not the subject.",example:"Ask me about literally anything else. Please.",intensity:3,rarity:"distinctive",pol:{ego:-1}},
{id:150068,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"Permission that is never going to come",desc:"Wants to be released by someone who is dead or gone, and needs to release themselves.",example:"He'd have to say it. And he's not going to say it.",intensity:5,rarity:"signature",pol:{emo:1,ego:-1}},
{id:150069,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"To be wrong in front of somebody",desc:"Wants to be right; needs to survive being publicly mistaken exactly once.",example:"I've never had to say it out loud. Not once in twenty years.",intensity:3,rarity:"distinctive",pol:{ego:-1,hon:1}},
{id:150070,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"Somewhere the story isn't already known",desc:"Wants to be understood; needs a place where nobody has the file.",example:"Everybody here knows. I'd like to be somewhere nobody knows.",intensity:3,rarity:"distinctive",pol:{warm:-1}},
{id:150071,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"To be asked to stay",desc:"Wants to be independent; needs, once, to be actively kept.",example:"Everyone's always let me go very easily.",intensity:4,rarity:"signature",pol:{emo:1,ego:-1}},
{id:150072,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"Less money and more time",desc:"Wants security; needs to discover the number was never the problem.",example:"I could stop. I've been able to stop for six years.",intensity:2,rarity:"uncommon",pol:{disc:-1}},
{id:150073,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"To be believed without evidence",desc:"Wants to be proved right; needs one person who never required the proof.",example:"I've got the paperwork. I've always had the paperwork.",intensity:4,rarity:"distinctive",pol:{emo:1,hon:1}},
{id:150074,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"An hour with somebody who knew them at nineteen",desc:"Wants to move on; needs contact with the version of themselves they abandoned.",example:"There's nobody left who remembers me before.",intensity:3,rarity:"signature",pol:{emo:1}},
{id:150075,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"To be told to stop",desc:"Wants to be trusted with it; needs someone with the standing to call time.",example:"Nobody's got the authority to tell me no any more. That's the problem.",intensity:5,rarity:"signature",pol:{disc:1,ego:-1}},
{id:150076,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"A smaller life, chosen on purpose",desc:"Wants more; needs to find out that less was available all along and is not a defeat.",example:"I keep waiting to be allowed to want something ordinary.",intensity:1,rarity:"distinctive",pol:{act:-1,mood:1}},
{id:150077,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"To be interrupted",desc:"Wants the floor; needs somebody who will take it back off them.",example:"<i>(twenty minutes in, and nobody has ever once stopped him)</i>",intensity:1,rarity:"uncommon",pol:{vol:-1}},
{id:150078,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"To find out it was ordinary",desc:"Wants their suffering recognised as exceptional; needs to learn it was common, which is the thing that would actually end the isolation.",example:"You mean other people — ? — Oh.",intensity:5,rarity:"signature",pol:{ego:-1,warm:1}},
{id:150079,section:"Motivation & Wound",category:"The Need (what would actually help)",trait:"Somebody to be bored with",desc:"Wants intensity; needs the flat, ordinary hours that intensity has been standing in for.",example:"We've never once just sat in a room together.",intensity:2,rarity:"distinctive",pol:{warm:1,act:-1}},

/* ---- The Ghost (who or what it's attached to) ---- */
{id:150090,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"A teacher and eleven words",desc:"Eleven words, thirty years ago, from someone who has certainly forgotten.",example:"Mrs Hallam. Second year. 'You're not the clever one, are you.'",intensity:4,rarity:"signature",pol:{ego:-1}},
{id:150091,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"A sibling who did better",desc:"Not a rival — simply the person every measurement is silently taken against.",example:"Well, obviously. Compared to Michael.",intensity:3,rarity:"distinctive",pol:{ego:-1}},
{id:150092,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"The house they were made to leave",desc:"A building, not a person, and the loss behaves exactly like a bereavement.",example:"<i>(still drives past it. Has for eleven years.)</i>",intensity:4,rarity:"distinctive",pol:{emo:1,pos:-1}},
{id:150093,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"A friend who stopped answering",desc:"No falling-out, no explanation, and no closure available.",example:"I never found out what I did. I'm not sure I did anything.",intensity:3,rarity:"distinctive",pol:{warm:-1,ego:-1}},
{id:150094,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"The version of themselves at twenty-two",desc:"The ghost is not another person; it is who they were going to be.",example:"That one would take one look at this and walk straight back out.",intensity:4,rarity:"signature",pol:{pos:-1,ego:-1}},
{id:150095,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"A parent who was almost good",desc:"The near-miss is the injury; a straightforwardly bad one would have been simpler.",example:"He tried. That's the whole trouble. He genuinely tried.",intensity:4,rarity:"signature",pol:{emo:1}},
{id:150096,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"An evening only they were present for",desc:"A small evening that reorganised everything, and they were the only one paying attention.",example:"It was March. You were all there. None of you know what I'm talking about.",intensity:5,rarity:"signature",pol:{emo:1}},
{id:150097,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"A dog",desc:"Genuinely and unembarrassedly the largest loss of their life so far.",example:"I know how that sounds. It's still true.",intensity:2,rarity:"distinctive",pol:{emo:1,warm:1}},
{id:150098,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"The letter they didn't send",desc:"Attached to their own inaction rather than to anyone else's.",example:"<i>(third drawer. Nine years old. Still sealed.)</i>",intensity:4,rarity:"signature",pol:{ego:-1,hon:1}},
{id:150099,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"A country they can't go back to",desc:"Not exile exactly — the place is still there and the version of it they knew is not.",example:"It exists. I've seen the photographs. It's not the same place.",intensity:4,rarity:"distinctive",pol:{pos:-1}},
{id:150100,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"Somebody still alive and unreachable",desc:"Not dead, not estranged, and entirely gone — which is harder to grieve.",example:"She's forty minutes away. I could get in the car right now.",intensity:5,rarity:"signature",pol:{emo:1}},
{id:150101,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"A photograph nobody can identify",desc:"An object that has become a person, and cannot be checked against anything.",example:"That's my grandmother. Probably. Everyone who'd know is dead.",intensity:2,rarity:"distinctive",pol:{}},
{id:150102,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"The job they were sacked from",desc:"A professional injury carried entirely privately, for a very long time.",example:"I say I left. I didn't leave.",intensity:3,rarity:"distinctive",pol:{ego:-1,hon:-1}},
{id:150103,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"A stranger at a bus stop",desc:"Someone they spoke to for six minutes and have thought about ever since.",example:"I never got her name. I think about it constantly, which is insane.",intensity:1,rarity:"signature",pol:{emo:1}},
{id:150104,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"Their own younger child",desc:"Attached to a person still in the house, who has grown out of the version they loved most.",example:"He's fine. He's absolutely fine. He's just not — <i>(stops)</i>",intensity:5,rarity:"signature",pol:{emo:1,warm:1}},
{id:150105,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"A small unpunished cruelty of their own",desc:"The ghost is something they did, to someone who never mentioned it again.",example:"She won't remember. I'd be amazed if she remembered.",intensity:4,rarity:"signature",pol:{hon:1,ego:-1}},
{id:150106,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"An empty chair at every occasion",desc:"A loss so continuously present it has become a piece of the furniture.",example:"<i>(nobody sits there. Nobody has ever discussed why.)</i>",intensity:3,rarity:"distinctive",pol:{emo:1}},
{id:150107,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"A song they will leave a room for",desc:"A small, absolute, entirely unexplained rule.",example:"<i>(four bars, and the coat is already on)</i>",intensity:1,rarity:"distinctive",pol:{emo:1}},
{id:150108,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"The person they were unfaithful to",desc:"Attached to the injured party rather than to the affair.",example:"I don't think about her. I think about him, constantly.",intensity:4,rarity:"signature",pol:{hon:1,emo:1}},
{id:150109,section:"Motivation & Wound",category:"The Ghost (who or what it's attached to)",trait:"A war nobody here has heard of",desc:"An event of enormous private significance and no local currency at all.",example:"You wouldn't have seen it on the news. It was quite small.",intensity:5,rarity:"signature",pol:{emo:-1,pos:-1}},

/* ---- The Defence (what they built on top) ---- */
{id:150120,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"Competence as a wall",desc:"Being extremely good at something specific means never having to be anything else.",example:"I'm not here to be liked. I'm here because I'm the best at this.",intensity:3,rarity:"distinctive",pol:{disc:1,emo:-1}},
{id:150121,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"Never still long enough to be caught",desc:"Never still long enough for anything to catch up, and calls it being busy.",example:"Can't, sorry — mad week. Next month's mad too, actually.",intensity:3,rarity:"distinctive",pol:{act:1,emo:-1}},
{id:150122,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"Being the funny one",desc:"A joke arrives reliably at the exact moment something real might.",example:"<i>(perfect timing, every time, for eleven years)</i>",intensity:3,rarity:"distinctive",pol:{emo:-1,warm:1}},
{id:150123,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"Low expectations, announced early",desc:"Pre-emptively lowers what anyone might want from them, so nothing can be a disappointment.",example:"I'm terrible at this sort of thing. Genuinely. Don't rely on me.",intensity:3,rarity:"distinctive",pol:{ego:-1,agr:1}},
{id:150124,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"Leaving first",desc:"Ends every relationship at the point where it might have started to matter.",example:"It was going really well, actually. That's about when I stopped.",intensity:4,rarity:"signature",pol:{emo:-1,warm:-1}},
{id:150125,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"Total honesty as armour",desc:"Says the unsayable so freely that nobody notices there is a great deal being kept back.",example:"I'll tell you anything. — <i>(and does, except for the one thing)</i>",intensity:4,rarity:"signature",pol:{hon:1,emo:-1}},
{id:150126,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"An enormous circle of acquaintances",desc:"Knows everyone, which is an efficient way of being close to nobody.",example:"<i>(three hundred people at the party. Nobody to ring on Sunday.)</i>",intensity:3,rarity:"distinctive",pol:{warm:1,emo:-1}},
{id:150127,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"Doing the difficult version on purpose",desc:"Chooses the harder path so that failing at it means nothing.",example:"Well, obviously it didn't work. Nobody could have done it that way.",intensity:4,rarity:"distinctive",pol:{ego:-1,disc:1}},
{id:150128,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"Volunteering for the worst job",desc:"Takes on what nobody wants, which purchases a standing that cannot be questioned.",example:"Give me the Christmas rota. No, honestly, give me it.",intensity:3,rarity:"distinctive",pol:{agr:1,ego:-1}},
{id:150129,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"Knowing everything about you",desc:"Asks so effectively that the conversation never turns around.",example:"<i>(two hours; you have learned nothing about him at all)</i>",intensity:4,rarity:"signature",pol:{cur:1,emo:-1}},
{id:150130,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"Rules for everyone",desc:"Built a code so comprehensive that no situation can arrive unprepared for.",example:"We don't do that in this house. We've never done that.",intensity:4,rarity:"distinctive",pol:{disc:1,rebel:-1}},
{id:150131,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"Being needed by something that can't leave",desc:"Attaches to dependents, animals or obligations that structurally cannot reject them.",example:"The horses don't get bored of me.",intensity:4,rarity:"signature",pol:{warm:1,emo:-1}},
{id:150132,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"Says the worst of it first",desc:"Says the worst thing about themselves before anyone else can, which takes it off the table.",example:"I know. I'm the last person who should be saying this.",intensity:2,rarity:"distinctive",pol:{ego:-1,hon:1}},
{id:150133,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"A very small life, kept perfect",desc:"Reduced the surface area until nothing could go wrong on it.",example:"Same route, same shop, same four people. It works.",intensity:3,rarity:"distinctive",pol:{disc:1,cur:-1}},
{id:150134,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"Aggressive generosity",desc:"Gives so much and so fast that nobody can find the balance point to give back.",example:"No. No. It's done. It's already paid for.",intensity:4,rarity:"signature",pol:{warm:1,asrt:1}},
{id:150135,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"Explaining themselves at length",desc:"Supplies so much context that there is never a gap for a question.",example:"— and the reason for that is, and this goes back to —",intensity:3,rarity:"distinctive",pol:{vol:1,emo:-1}},
{id:150136,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"An appetite for other people's crises",desc:"Always in the middle of someone else's emergency, which is a full-time way of not being in their own.",example:"I can't right now — Sam's in a state, I have to go.",intensity:3,rarity:"distinctive",pol:{warm:1,act:1}},
{id:150137,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"Refusing to be impressed",desc:"Nothing lands, which means nothing can be taken away.",example:"It's alright. Yeah. It's alright.",intensity:2,rarity:"distinctive",pol:{pos:-1,emo:-1}},
{id:150138,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"Being early to everything",desc:"Arrives first everywhere, which means never walking into a room already in progress.",example:"<i>(twenty-five minutes early, in the car, waiting)</i>",intensity:1,rarity:"signature",pol:{disc:1,ego:-1}},
{id:150139,section:"Motivation & Wound",category:"The Defence (what they built on top)",trait:"One friend, load-bearing",desc:"Everything routes through a single relationship, which is efficient and structurally terrifying.",example:"I'd have to ask Ruth. — Yeah, I'd have to ask Ruth about that too.",intensity:5,rarity:"signature",pol:{warm:1,emo:1}},

/* ================================================================
   3. APPEARANCE — the i1 and i5 tails
   ================================================================ */
{id:150150,section:"Appearance",category:"Build — Imposing",trait:"Slightly wider than expected",desc:"Not large — just consistently a size up from what people had estimated.",example:"<i>(the doorway is fine, and there is less of it than there was)</i>",intensity:1,rarity:"common",pol:{}},
{id:150151,section:"Appearance",category:"Build — Imposing",trait:"Changes the acoustics of a room",desc:"So physically present that the sound of a space alters when they enter it.",example:"<i>(the room got quieter, and not because anyone stopped talking)</i>",intensity:5,rarity:"signature",pol:{}},
{id:150152,section:"Appearance",category:"Build — Imposing",trait:"Hands that end a conversation",desc:"Enormous and entirely unremarked upon, and everyone adjusts.",example:"<i>(the mug looks like a thimble and nobody says anything)</i>",intensity:5,rarity:"distinctive",pol:{}},
{id:150153,section:"Appearance",category:"Build — Slight",trait:"A half-size too small for the coat",desc:"Everything they wear was bought for a slightly larger person.",example:"<i>(cuffs at the knuckle)</i>",intensity:1,rarity:"common",pol:{}},
{id:150154,section:"Appearance",category:"Build — Slight",trait:"Looks like they might not eat",desc:"Thin to the point that strangers comment, and have for years.",example:"<i>(the second offer of food in ten minutes)</i>",intensity:5,rarity:"distinctive",pol:{}},
{id:150155,section:"Appearance",category:"Build — Slight",trait:"Disappears behind furniture",desc:"So slight that they are genuinely, repeatedly, physically overlooked.",example:"Sorry — I didn't see you there. — <i>(again)</i>",intensity:5,rarity:"signature",pol:{}},
{id:150156,section:"Appearance",category:"Upkeep — Immaculate",trait:"Shoes always clean",desc:"One standard, quietly maintained, in an otherwise ordinary presentation.",example:"<i>(whatever the weather, whatever the day)</i>",intensity:1,rarity:"common",pol:{disc:1}},
{id:150157,section:"Appearance",category:"Upkeep — Immaculate",trait:"Not a thread out of place, ever",desc:"A completeness of presentation so total it reads as a statement, and is one.",example:"<i>(at six in the morning, in a hospital corridor, immaculate)</i>",intensity:5,rarity:"signature",pol:{disc:1,ego:1}},
{id:150158,section:"Appearance",category:"Upkeep — Immaculate",trait:"Visibly ironed everything",desc:"Every garment pressed, including the ones nobody irons.",example:"<i>(a crease down the front of the jeans)</i>",intensity:5,rarity:"distinctive",pol:{disc:1}},
{id:150159,section:"Appearance",category:"Upkeep — Unkempt",trait:"One button undone",desc:"A single small disorder in an otherwise ordinary turnout.",example:"<i>(cuff hanging open all day; hasn't noticed)</i>",intensity:1,rarity:"common",pol:{disc:-1}},
{id:150160,section:"Appearance",category:"Upkeep — Unkempt",trait:"Beyond neglect and into evidence",desc:"State of dress that has stopped being untidiness and become information about their week.",example:"<i>(nobody asks. Everybody has noticed.)</i>",intensity:5,rarity:"signature",pol:{disc:-1,mood:-1}},
{id:150161,section:"Appearance",category:"Upkeep — Unkempt",trait:"Hair cut by themselves",desc:"Obviously, repeatedly, and without embarrassment.",example:"<i>(the back is a different length from the front)</i>",intensity:5,rarity:"distinctive",pol:{disc:-1,rebel:1}},
{id:150162,section:"Appearance",category:"Presence — Striking",trait:"One feature people describe first",desc:"Otherwise ordinary; there is a single thing everybody leads with.",example:"You know — tall bloke — the eyebrows.",intensity:1,rarity:"common",pol:{}},
{id:150163,section:"Appearance",category:"Presence — Striking",trait:"People stop mid-sentence",desc:"An arrival that visibly interrupts whatever the room was doing.",example:"<i>(three conversations lost the thread at once)</i>",intensity:5,rarity:"signature",pol:{}},
{id:150164,section:"Appearance",category:"Presence — Striking",trait:"Photographed by strangers",desc:"Distinctive enough that it happens, and has happened often enough to be tiring.",example:"<i>(the phone comes up again, across the platform)</i>",intensity:5,rarity:"distinctive",pol:{}},
{id:150165,section:"Appearance",category:"Presence — Unremarkable",trait:"Described by their job",desc:"Nothing physical comes to mind, so people reach for what they do instead.",example:"You know — from the office — the accounts one.",intensity:1,rarity:"common",pol:{}},
{id:150166,section:"Appearance",category:"Presence — Unremarkable",trait:"Cannot be picked out of a group",desc:"So thoroughly unremarkable that people who know them well fail to spot them.",example:"<i>(waved for a full minute. She was looking straight at him.)</i>",intensity:5,rarity:"signature",pol:{}},
{id:150167,section:"Appearance",category:"Presence — Unremarkable",trait:"Repeatedly mistaken for someone else",desc:"Has the kind of face that is apparently also several other people's face.",example:"I get it about once a fortnight. I've stopped correcting them.",intensity:5,rarity:"distinctive",pol:{}},
{id:150168,section:"Appearance",category:"Movement & Bearing",trait:"Turns with the whole body",desc:"A small stiffness in the neck that shows in every turn.",example:"<i>(shoulders come round with the head)</i>",intensity:1,rarity:"common",pol:{}},
{id:150169,section:"Appearance",category:"Movement & Bearing",trait:"Moves like the floor might give",desc:"Every step tested, everywhere, with no apparent cause.",example:"<i>(weight on the back foot until the front one is sure)</i>",intensity:5,rarity:"signature",pol:{}},
{id:150170,section:"Appearance",category:"Movement & Bearing",trait:"Cannot be hurried",desc:"Moves at exactly one speed regardless of circumstance, including emergencies.",example:"<i>(the same pace across the burning yard)</i>",intensity:5,rarity:"distinctive",pol:{pace:-1,act:-1}},
{id:150171,section:"Appearance",category:"Distinguishing Marks",trait:"A slightly crooked finger",desc:"An old small break, set imperfectly, entirely unremarked.",example:"<i>(the ring finger doesn't quite straighten)</i>",intensity:1,rarity:"common",pol:{}},
{id:150172,section:"Appearance",category:"Distinguishing Marks",trait:"Marked where it cannot be hidden",desc:"A permanent, unmissable feature that shapes every first meeting they will ever have.",example:"<i>(from the jaw to the collarbone; people decide about it before he speaks)</i>",intensity:5,rarity:"signature",pol:{}},
{id:150173,section:"Appearance",category:"Distinguishing Marks",trait:"Missing something people count",desc:"An absence that is noticed immediately and asked about never.",example:"<i>(two fingers on the left hand. Nobody has ever raised it.)</i>",intensity:5,rarity:"distinctive",pol:{}},

/* ================================================================
   4. THE UNREACHABLE SETTINGS
   ----------------------------------------------------------------
   Micro-Physical Tics ran 3 at i4 and 2 at i5; Conceptual Framework
   & Loanwords 4 and 3 — so "aggressively jargon-heavy" was a slider
   position with almost nothing behind it.
   ================================================================ */
{id:150180,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Whole face resets between sentences",desc:"A visible, complete clearing of expression, several times a minute.",example:"<i>(everything drops, then rebuilds)</i>",intensity:4,rarity:"distinctive",pol:{emo:-1}},
{id:150181,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Jaw works constantly",desc:"A continuous grinding motion that is audible in a quiet room.",example:"<i>(you can hear it from the next chair)</i>",intensity:4,rarity:"common",pol:{mood:-1}},
{id:150182,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Flinches at ordinary sounds",desc:"A full startle response to doors, cutlery and raised voices, many times a day.",example:"<i>(the plate goes down and the whole body goes)</i>",intensity:5,rarity:"distinctive",pol:{mood:-1,emo:1}},
{id:150183,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Both hands never stop",desc:"Continuous, large, unmissable manipulation of anything within reach.",example:"<i>(the napkin is now in fourteen pieces)</i>",intensity:4,rarity:"common",pol:{act:1}},
{id:150184,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Head tremor under attention",desc:"A pronounced shake that arrives precisely when they are being watched.",example:"<i>(steady all morning; not now)</i>",intensity:5,rarity:"signature",pol:{ego:-1}},
{id:150185,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Blinks in long hard sequences",desc:"Runs of five or six forceful blinks, several times a conversation.",example:"<i>(the eyes close hard, repeatedly, then it passes)</i>",intensity:4,rarity:"distinctive",pol:{}},
{id:150186,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Rocks when concentrating",desc:"A large, sustained, entirely unconscious rhythm.",example:"<i>(the chair has been moving for twenty minutes)</i>",intensity:4,rarity:"uncommon",pol:{}},
{id:150187,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Touches their own face constantly",desc:"Mouth, jaw, temple, back to mouth, without pause, at unmissable frequency.",example:"<i>(the hand has not left the face in five minutes)</i>",intensity:5,rarity:"common",pol:{ego:-1}},

{id:150190,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Jargon-dense past the point of use",desc:"Terminology so thick that colleagues in the same field have to slow them down.",example:"The stochastic layer's non-ergodic under those priors, obviously.",intensity:5,rarity:"distinctive",pol:{intel:1,form:1}},
{id:150191,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Refuses the plain word on principle",desc:"Actively rejects the everyday term when offered it, at length.",example:"It's not 'a delay'. It's latency. They're not the same thing.",intensity:5,rarity:"distinctive",pol:{intel:1,agr:-1}},
{id:150192,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Three loanwords a sentence",desc:"Heavy, continuous borrowing from several languages, unglossed.",example:"There's a certain Gemütlichkeit to it, a sprezzatura, if you like — a je ne sais quoi.",intensity:4,rarity:"distinctive",pol:{form:1}},
{id:150193,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Everything is a framework",desc:"Applies a formal conceptual apparatus to every subject including the domestic ones, insistently.",example:"What's your model of the argument? What are we actually optimising for here?",intensity:5,rarity:"signature",pol:{intel:1,emo:-1}},
{id:150194,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Acronyms without expansion",desc:"Speaks almost entirely in initialisms and never once unpacks one.",example:"The RFI's blocked on the SOW until the PMO sign the CR.",intensity:4,rarity:"common",pol:{form:1}},
{id:150195,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Cites the source mid-sentence",desc:"Attaches an attribution to every borrowed idea, continuously.",example:"— which is Goffman, obviously, though Bourdieu would say —",intensity:4,rarity:"distinctive",pol:{intel:1,ego:1}},
{id:150196,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Coins terminology and enforces it",desc:"Invents a vocabulary for their own domain and corrects anyone who uses another.",example:"We don't call it that. We call it the handover surface.",intensity:5,rarity:"signature",pol:{intel:1,asrt:1}},
{id:150197,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"One discipline explains everything",desc:"Reduces every subject to the terms of a single field, relentlessly.",example:"It's a supply problem. Marriage. It's fundamentally a supply problem.",intensity:4,rarity:"distinctive",pol:{intel:1,cur:-1}},
];

TRAITS.push(...TRAITS_TAILS2);
